//! Differential oracle generated by the unchanged original JS worker/native scanner.
use quicktool_rust::index;
use rusqlite::params;
use serde::Deserialize;
use serde_json::json;
use std::{
    path::{Path, PathBuf},
    time::{Duration, Instant},
};

#[derive(Deserialize)]
struct Oracle {
    entries: Vec<Row>,
    cases: Vec<Case>,
    files: Vec<FixtureFile>,
}
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Row {
    path: String,
    name: String,
    search: String,
    is_dir: bool,
    size: u64,
    tokens: Vec<String>,
}
#[derive(Deserialize)]
struct Case {
    name: String,
    query: String,
    limit: usize,
    expected: Vec<Expected>,
}
#[derive(Debug, Deserialize, PartialEq, Eq, serde::Serialize)]
#[serde(rename_all = "camelCase")]
struct Expected {
    path: String,
    name: String,
    is_dir: bool,
}
#[derive(Deserialize)]
struct FixtureFile {
    relative: String,
    directory: bool,
}
fn oracle() -> Oracle {
    serde_json::from_str(include_str!("index-oracle.json")).unwrap()
}
fn seeded(oracle: &Oracle) -> rusqlite::Connection {
    let db = index::open(Path::new(":memory:")).unwrap();
    db.execute_batch("BEGIN").unwrap();
    for row in &oracle.entries {
        db.execute("INSERT INTO entries(path,name,search,root,generation,is_dir,size,modified,search_path) VALUES(?,?,?,'C:\\QuickToolSynthetic',1,?,?,0,?)",
    params![row.path,row.name,row.search,row.is_dir,row.size,normalized(&row.path)]).unwrap();
        for token in &row.tokens {
            db.execute(
                "INSERT INTO tokens(token,entry_id) SELECT ?,rowid FROM entries WHERE path=?",
                params![token, row.path],
            )
            .unwrap();
        }
    }
    db.execute_batch("COMMIT").unwrap();
    db
}
fn normalized(value: &str) -> String {
    use unicode_normalization::UnicodeNormalization;
    value.nfkc().flat_map(char::to_lowercase).collect()
}
fn expected(item: index::FileEntry) -> Expected {
    Expected {
        path: item.path,
        name: item.name,
        is_dir: item.is_dir,
    }
}
#[test]
fn queries_match_original_worker_oracle() {
    let fixture = oracle();
    let db = seeded(&fixture);
    let mut failures = Vec::new();
    let mut report = Vec::new();
    for case in fixture.cases {
        let begin = Instant::now();
        let actual = index::query(&db, &case.query, case.limit)
            .map(|rows| rows.into_iter().map(expected).collect::<Vec<_>>());
        let elapsed = begin.elapsed();
        let matched = actual.as_ref().is_ok_and(|rows| *rows == case.expected);
        let query_units = case.query.encode_utf16().count();
        if !matched {
            failures.push(format!(
                "{} (UTF16 {},limit {}): expected {} [{}], actual {}",
                case.name,
                query_units,
                case.limit,
                case.expected.len(),
                case.expected
                    .iter()
                    .take(5)
                    .map(|e| e.name.as_str())
                    .collect::<Vec<_>>()
                    .join(", "),
                match &actual {
                    Ok(rows) => format!(
                        "{} [{}]",
                        rows.len(),
                        rows.iter()
                            .take(5)
                            .map(|e| e.name.as_str())
                            .collect::<Vec<_>>()
                            .join(", ")
                    ),
                    Err(error) => error.to_string(),
                }
            ));
        }
        report.push(json!({"name":case.name,"queryUtf16":query_units,"matched":matched,"expected":case.expected,"actual":actual.as_ref().ok(),"error":actual.as_ref().err().map(ToString::to_string),"elapsedUs":elapsed.as_micros()}));
    }
    let report_path =
        Path::new(env!("CARGO_MANIFEST_DIR")).join(".qa/index-rust-query-parity.json");
    std::fs::create_dir_all(report_path.parent().unwrap()).unwrap();
    std::fs::write(report_path, serde_json::to_vec_pretty(&report).unwrap()).unwrap();
    assert!(
        failures.is_empty(),
        "{} original-worker query mismatches:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

fn quicktool_qa_base() -> PathBuf {
    // QA scratch base; override with QUICKTOOL_QA_BASE, defaults to the system temp dir.
    std::env::var_os("QUICKTOOL_QA_BASE")
        .map(PathBuf::from)
        .unwrap_or_else(std::env::temp_dir)
}

struct SyntheticRoot(PathBuf);
impl SyntheticRoot {
    fn new() -> Self {
        let base = quicktool_qa_base();
        let mut random = [0u8; 8];
        getrandom::fill(&mut random).unwrap();
        let path = base.join(format!(
            "quicktool-index-parity-{:016x}",
            u64::from_le_bytes(random)
        ));
        std::fs::create_dir_all(&path).unwrap();
        Self(path)
    }
}
impl Drop for SyntheticRoot {
    fn drop(&mut self) {
        if let Ok(path) = self.0.canonicalize() {
            let base = quicktool_qa_base().canonicalize().unwrap();
            assert!(
                path.starts_with(base)
                    && path
                        .file_name()
                        .unwrap()
                        .to_string_lossy()
                        .starts_with("quicktool-index-parity-")
            );
            std::fs::remove_dir_all(path).unwrap();
        }
    }
}
#[test]
fn real_scan_normalization_and_order_match_original_worker() {
    let oracle = oracle();
    let directory = SyntheticRoot::new();
    let root = directory.0.join("files");
    std::fs::create_dir_all(&root).unwrap();
    for file in &oracle.files {
        let path = root.join(&file.relative);
        if file.directory {
            std::fs::create_dir_all(path).unwrap();
        } else {
            std::fs::create_dir_all(path.parent().unwrap()).unwrap();
            std::fs::write(path, b"synthetic index fixture").unwrap();
        }
    }
    let started = Instant::now();
    let worker = index::Index::start(
        directory.0.join("rust.sqlite"),
        vec![root.clone()],
        vec!["EXCLUDED".into()],
        || {},
    );
    let mut ready = false;
    let deadline = Instant::now() + Duration::from_secs(30);
    while Instant::now() < deadline {
        if let Ok(index::Response::Status(status)) =
            worker.responses.recv_timeout(Duration::from_millis(200))
        {
            assert!(status.error.is_none(), "scan error {:?}", status.error);
            if !status.building {
                assert_eq!(status.count, oracle.entries.len() as u64);
                ready = true;
                break;
            }
        }
    }
    assert!(ready, "scan timeout");
    let scan_ms = started.elapsed().as_secs_f64() * 1000.;
    let mut failures = Vec::new();
    for (i, case) in oracle
        .cases
        .iter()
        .filter(|case| {
            matches!(
                case.name.as_str(),
                "needle"
                    | "greekFinalSigma"
                    | "greekUpper"
                    | "fullwidthName"
                    | "localeSort"
                    | "lengthSort"
                    | "limit-1"
                    | "excluded"
                    | "unicode16Ascii"
                    | "unicode16Literal"
                    | "markGram"
            )
        })
        .enumerate()
    {
        let serial = i as u64 + 1;
        worker
            .requests
            .send(index::Request::Search {
                serial,
                query: case.query.clone(),
                limit: case.limit,
            })
            .unwrap();
        let deadline = Instant::now() + Duration::from_secs(10);
        let mut result = None;
        while Instant::now() < deadline {
            if let Ok(index::Response::Results {
                serial: actual,
                items,
            }) = worker.responses.recv_timeout(Duration::from_millis(200))
            {
                if actual == serial {
                    result = Some(items);
                    break;
                }
            }
        }
        let actual = result
            .expect("query timeout")
            .into_iter()
            .map(|mut item| {
                item.path = item
                    .path
                    .replace(&*root.to_string_lossy(), "C:\\QuickToolSynthetic");
                expected(item)
            })
            .collect::<Vec<_>>();
        if actual != case.expected {
            failures.push(format!(
                "{} expected [{}], actual [{}]",
                case.name,
                case.expected
                    .iter()
                    .take(5)
                    .map(|e| e.name.as_str())
                    .collect::<Vec<_>>()
                    .join(", "),
                actual
                    .iter()
                    .take(5)
                    .map(|e| e.name.as_str())
                    .collect::<Vec<_>>()
                    .join(", ")
            ));
        }
    }
    drop(worker);
    println!(
        "Rust synthetic scan {} entries in {scan_ms:.3} ms",
        oracle.entries.len()
    );
    assert!(
        failures.is_empty(),
        "{} real scan oracle mismatches:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

/// Run after `pwsh -File scripts/capture-index.ps1 -Count 10000 -Output .qa/index-10000-original.json`.
/// Timing is reported without machine-dependent pass/fail thresholds.
#[test]
#[ignore = "explicit synthetic 10,000-file performance audit"]
fn synthetic_10000_scan_and_query_benchmark() {
    let file = Path::new(env!("CARGO_MANIFEST_DIR")).join(".qa/index-10000-original.json");
    let data: Oracle =
        serde_json::from_slice(&std::fs::read(file).expect("capture 10,000-entry oracle first"))
            .unwrap();
    assert!(data.entries.len() >= 10000);
    let db = seeded(&data);
    let mut timings = Vec::new();
    for i in 0..110 {
        let begin = Instant::now();
        let result = index::query(&db, if i % 3 == 0 { "*needle*" } else { "needle" }, 40).unwrap();
        assert_eq!(result.len(), 40);
        if i >= 10 {
            timings.push(begin.elapsed().as_secs_f64() * 1000.);
        }
    }
    timings.sort_by(f64::total_cmp);
    let directory = SyntheticRoot::new();
    let root = directory.0.join("files");
    std::fs::create_dir_all(&root).unwrap();
    for entry in &data.files {
        let path = root.join(&entry.relative);
        if entry.directory {
            std::fs::create_dir_all(path).unwrap();
        } else {
            std::fs::create_dir_all(path.parent().unwrap()).unwrap();
            std::fs::write(path, b"synthetic index fixture").unwrap();
        }
    }
    let began = Instant::now();
    let worker = index::Index::start(
        directory.0.join("benchmark.sqlite"),
        vec![root],
        vec!["EXCLUDED".into()],
        || {},
    );
    let deadline = Instant::now() + Duration::from_secs(60);
    let mut count = None;
    while Instant::now() < deadline {
        if let Ok(index::Response::Status(status)) =
            worker.responses.recv_timeout(Duration::from_millis(200))
        {
            assert!(status.error.is_none(), "scan error {:?}", status.error);
            if !status.building {
                count = Some(status.count);
                break;
            }
        }
    }
    let scan_ms = began.elapsed().as_secs_f64() * 1000.;
    assert_eq!(count, Some(data.entries.len() as u64));
    let mut round_trips = Vec::new();
    for i in 0..110 {
        let serial = i + 1000;
        let query = if i % 3 == 0 { "*needle*" } else { "needle" };
        let begin = Instant::now();
        worker
            .requests
            .send(index::Request::Search {
                serial,
                query: query.into(),
                limit: 40,
            })
            .unwrap();
        loop {
            match worker
                .responses
                .recv_timeout(Duration::from_secs(10))
                .expect("benchmark query timeout")
            {
                index::Response::Results {
                    serial: current,
                    items,
                } if current == serial => {
                    assert_eq!(items.len(), 40);
                    break;
                }
                index::Response::Status(status) => {
                    assert!(status.error.is_none(), "query error {:?}", status.error)
                }
                _ => {}
            }
        }
        if i >= 10 {
            round_trips.push(begin.elapsed().as_secs_f64() * 1000.);
        }
    }
    drop(worker);
    let database_bytes = std::fs::metadata(directory.0.join("benchmark.sqlite"))
        .unwrap()
        .len();
    round_trips.sort_by(f64::total_cmp);
    let report = json!({"rows":data.entries.len(),"scanMs":scan_ms,"databaseBytes":database_bytes,"normalizationUnicode":unicode_normalization::UNICODE_VERSION,
        "queryMedianMs":round_trips[50],"queryP95Ms":round_trips[95],"queryIncludesWorkerRoundTrip":true,
        "directQueryMedianMs":timings[50],"directQueryP95Ms":timings[95],
        "buildProfile":if cfg!(debug_assertions) {"debug"} else {"release"}});
    println!("{report}");
    std::fs::write(
        Path::new(env!("CARGO_MANIFEST_DIR")).join(".qa/index-10000-rust.json"),
        serde_json::to_vec_pretty(&report).unwrap(),
    )
    .unwrap();
}
